import { TriviaQuestion } from '../trivia-types'

export const HISTORY_QUESTIONS: TriviaQuestion[] = [
  { id: 'hist-1', category: 'history', difficulty: 'easy', question: 'What ancient wonder was located in Giza, Egypt?', answer: 'The Great Pyramid', options: ['The Colossus', 'The Great Pyramid', 'The Hanging Gardens', 'The Lighthouse'], explanation: 'The Great Pyramid of Giza was built around 2560 BC for Pharaoh Khufu. It is the oldest and only surviving wonder of the ancient world.' },
  { id: 'hist-2', category: 'history', difficulty: 'easy', question: 'What year did Christopher Columbus first reach the Americas?', answer: '1492', options: ['1488', '1492', '1498', '1502'], explanation: 'Columbus landed in the Bahamas on October 12, 1492, on a voyage funded by Spain. He made four total voyages to the New World.' },
  { id: 'hist-3', category: 'history', difficulty: 'easy', question: 'Who was the first Emperor of Rome?', answer: 'Augustus', options: ['Julius Caesar', 'Augustus', 'Nero', 'Tiberius'], explanation: 'Augustus (born Octavian) became the first Roman Emperor in 27 BC after defeating Mark Antony. Julius Caesar was a dictator but never held the title of Emperor.' },
  { id: 'hist-4', category: 'history', difficulty: 'easy', question: 'What was the name of the ship the Pilgrims sailed to America in 1620?', answer: 'Mayflower', options: ['Mayflower', 'Santa Maria', 'Endeavour', 'Discovery'], explanation: 'The Mayflower carried 102 passengers from Plymouth, England, to Massachusetts. The passengers signed the Mayflower Compact, an early form of self-governance.' },
  { id: 'hist-5', category: 'history', difficulty: 'easy', question: 'The French Revolution began in what year?', answer: '1789', options: ['1776', '1789', '1799', '1804'], explanation: 'The French Revolution began in 1789 with the storming of the Bastille on July 14. It led to the end of the monarchy and the rise of Napoleon Bonaparte.' },
  { id: 'hist-6', category: 'history', difficulty: 'easy', question: 'What ancient civilization built Machu Picchu?', answer: 'The Inca', options: ['The Maya', 'The Aztec', 'The Inca', 'The Olmec'], explanation: 'Machu Picchu was built by the Inca in the 15th century in modern-day Peru. It was rediscovered by American historian Hiram Bingham in 1911.' },
  { id: 'hist-7', category: 'history', difficulty: 'easy', question: 'What wall was built to protect northern England from Scottish tribes?', answer: "Hadrian's Wall", options: ["Hadrian's Wall", "Antonine's Wall", 'The Great Wall', 'Offa\'s Dyke'], explanation: "Hadrian's Wall was built beginning in AD 122 under Emperor Hadrian and stretched 73 miles across northern England. It marked the northern boundary of the Roman Empire in Britain." },
  { id: 'hist-8', category: 'history', difficulty: 'easy', question: 'What event is commonly considered the start of World War I?', answer: 'Assassination of Archduke Franz Ferdinand', options: ['Sinking of the Lusitania', 'Assassination of Archduke Franz Ferdinand', 'Invasion of Belgium', 'Treaty of Versailles'], explanation: 'Archduke Franz Ferdinand of Austria-Hungary was assassinated in Sarajevo on June 28, 1914, by Gavrilo Princip. This set off a chain of alliance obligations that escalated into a world war.' },
  { id: 'hist-9', category: 'history', difficulty: 'easy', question: 'What document did Martin Luther nail to the church door in 1517?', answer: 'The 95 Theses', options: ['The Magna Carta', 'The 95 Theses', 'The Declaration of Independence', 'The Communist Manifesto'], explanation: 'Martin Luther posted his 95 Theses on the door of the Castle Church in Wittenberg, Germany, protesting the sale of indulgences. This act is considered the spark of the Protestant Reformation.' },
  { id: 'hist-10', category: 'history', difficulty: 'easy', question: 'What empire was ruled by Genghis Khan?', answer: 'The Mongol Empire', options: ['The Ottoman Empire', 'The Mongol Empire', 'The Persian Empire', 'The Mughal Empire'], explanation: 'Genghis Khan united the Mongol tribes and founded the Mongol Empire in 1206. At its peak, it became the largest contiguous land empire in history.' },
  { id: 'hist-11', category: 'history', difficulty: 'easy', question: 'The Berlin Wall fell in what year?', answer: '1989', options: ['1987', '1988', '1989', '1991'], explanation: 'The Berlin Wall fell on November 9, 1989, after 28 years of dividing East and West Berlin. Germany was officially reunified on October 3, 1990.' },
  { id: 'hist-12', category: 'history', difficulty: 'easy', question: 'Who was the Greek god of the sea?', answer: 'Poseidon', options: ['Zeus', 'Poseidon', 'Hades', 'Apollo'], explanation: 'Poseidon was one of the twelve Olympian gods and brother to Zeus and Hades. The Romans called him Neptune.' },
  { id: 'hist-13', category: 'history', difficulty: 'easy', question: 'What was the primary writing material used in ancient Egypt?', answer: 'Papyrus', options: ['Parchment', 'Papyrus', 'Vellum', 'Clay tablets'], explanation: 'Papyrus was made from the papyrus plant that grew along the Nile River. The English word "paper" derives from the word papyrus.' },
  { id: 'hist-14', category: 'history', difficulty: 'easy', question: 'What city was the capital of the Byzantine Empire?', answer: 'Constantinople', options: ['Rome', 'Athens', 'Constantinople', 'Alexandria'], explanation: 'Constantinople (modern-day Istanbul) served as the capital of the Byzantine Empire for over 1,000 years. It was originally founded as Byzantium and renamed by Emperor Constantine in 330 AD.' },
  { id: 'hist-15', category: 'history', difficulty: 'easy', question: 'Who painted the ceiling of the Sistine Chapel?', answer: 'Michelangelo', options: ['Leonardo da Vinci', 'Raphael', 'Michelangelo', 'Donatello'], explanation: 'Michelangelo painted the Sistine Chapel ceiling between 1508 and 1512 at the request of Pope Julius II. The famous "Creation of Adam" panel is one of nine scenes from the Book of Genesis.' },
  { id: 'hist-16', category: 'history', difficulty: 'easy', question: 'What ancient trade route connected China to the Mediterranean?', answer: 'The Silk Road', options: ['The Spice Route', 'The Silk Road', 'The Amber Road', 'The Incense Route'], explanation: 'The Silk Road was a network of trade routes spanning about 4,000 miles, active from about the 2nd century BC. It facilitated trade in silk, spices, and ideas between East and West.' },
  { id: 'hist-17', category: 'history', difficulty: 'easy', question: 'What country did the United States purchase Louisiana from in 1803?', answer: 'France', options: ['Spain', 'France', 'England', 'Mexico'], explanation: 'The Louisiana Purchase was bought from Napoleon Bonaparte for about $15 million, roughly 4 cents per acre. It doubled the size of the United States overnight.' },
  { id: 'hist-18', category: 'history', difficulty: 'easy', question: 'Who led the Soviet Union during World War II?', answer: 'Joseph Stalin', options: ['Vladimir Lenin', 'Joseph Stalin', 'Nikita Khrushchev', 'Leon Trotsky'], explanation: 'Joseph Stalin led the Soviet Union from the mid-1920s until his death in 1953. The Battle of Stalingrad in 1942-43 was a major turning point of the war on the Eastern Front.' },
  { id: 'hist-19', category: 'history', difficulty: 'easy', question: 'What was the name of the Allied invasion of Normandy on June 6, 1944?', answer: 'D-Day', options: ['V-Day', 'D-Day', 'Operation Barbarossa', 'The Blitz'], explanation: 'D-Day, officially Operation Overlord, was the largest seaborne invasion in history with over 156,000 troops. Five beaches were targeted: Utah, Omaha, Gold, Juno, and Sword.' },
  { id: 'hist-20', category: 'history', difficulty: 'easy', question: 'What ancient civilization is credited with inventing the wheel?', answer: 'Mesopotamia', options: ['Egypt', 'Mesopotamia', 'China', 'India'], explanation: 'The wheel was invented in Mesopotamia (modern-day Iraq) around 3500 BC, originally for pottery-making. It was not used for transportation until about 300 years later.' },
  { id: 'hist-21', category: 'history', difficulty: 'easy', question: 'What famous document begins with "We the People"?', answer: 'The U.S. Constitution', options: ['The Declaration of Independence', 'The U.S. Constitution', 'The Bill of Rights', 'The Articles of Confederation'], explanation: 'The U.S. Constitution was signed on September 17, 1787, in Philadelphia. It replaced the weaker Articles of Confederation and established the framework for the federal government.' },
  { id: 'hist-22', category: 'history', difficulty: 'easy', question: 'What Renaissance artist painted the Mona Lisa?', answer: 'Leonardo da Vinci', options: ['Michelangelo', 'Raphael', 'Leonardo da Vinci', 'Botticelli'], explanation: 'Leonardo da Vinci painted the Mona Lisa between approximately 1503 and 1519. It has hung in the Louvre in Paris since the French Revolution.' },
  { id: 'hist-23', category: 'history', difficulty: 'easy', question: 'Who was the leader of Nazi Germany?', answer: 'Adolf Hitler', options: ['Adolf Hitler', 'Benito Mussolini', 'Heinrich Himmler', 'Joseph Goebbels'], explanation: 'Adolf Hitler rose to power as Chancellor of Germany in 1933 and declared himself Fuhrer in 1934. His invasion of Poland in September 1939 triggered World War II in Europe.' },
  { id: 'hist-24', category: 'history', difficulty: 'easy', question: 'The Magna Carta was signed in what country?', answer: 'England', options: ['France', 'England', 'Scotland', 'Spain'], explanation: 'The Magna Carta was signed in 1215 at Runnymede by King John under pressure from rebellious barons. It established the principle that everyone, including the king, was subject to the law.' },
  { id: 'hist-25', category: 'history', difficulty: 'easy', question: 'What empire built a network of roads across Europe, North Africa, and the Middle East?', answer: 'The Roman Empire', options: ['The Greek Empire', 'The Roman Empire', 'The Persian Empire', 'The Ottoman Empire'], explanation: 'At its peak, the Roman road network spanned over 250,000 miles across three continents. The phrase "All roads lead to Rome" reflects how the network centered on the capital.' },
  { id: 'hist-26', category: 'history', difficulty: 'easy', question: 'What was the last major battle of the American Revolution?', answer: 'Battle of Yorktown', options: ['Battle of Bunker Hill', 'Battle of Saratoga', 'Battle of Yorktown', 'Battle of Trenton'], explanation: 'The Battle of Yorktown in 1781 saw British General Cornwallis surrender to George Washington. French naval and ground forces played a crucial role in the American victory.' },
  { id: 'hist-27', category: 'history', difficulty: 'easy', question: 'What ancient structure in England is a ring of standing stones?', answer: 'Stonehenge', options: ['Stonehenge', 'Hadrian\'s Wall', 'The Colosseum', 'The Parthenon'], explanation: 'Stonehenge was built in several stages between roughly 3000 and 2000 BC on Salisbury Plain. Its exact purpose remains debated, but it aligns with the sunrise on the summer solstice.' },
  { id: 'hist-28', category: 'history', difficulty: 'easy', question: 'Who was the Egyptian queen known for her relationships with Julius Caesar and Mark Antony?', answer: 'Cleopatra', options: ['Nefertiti', 'Cleopatra', 'Hatshepsut', 'Isis'], explanation: 'Cleopatra VII was the last active ruler of the Ptolemaic Kingdom of Egypt, ruling from 51 to 30 BC. She died by suicide after the defeat of her forces by Octavian (Augustus).' },
  { id: 'hist-29', category: 'history', difficulty: 'easy', question: 'What invention by Johannes Gutenberg revolutionized communication around 1440?', answer: 'The printing press', options: ['The telescope', 'The printing press', 'The compass', 'The astrolabe'], explanation: 'Gutenberg\'s movable-type printing press made books affordable and widely available for the first time. His first major printed work was the Gutenberg Bible, completed around 1455.' },
  { id: 'hist-30', category: 'history', difficulty: 'easy', question: 'What war was fought between the North and South of the United States from 1861 to 1865?', answer: 'The Civil War', options: ['The Revolutionary War', 'The Civil War', 'The War of 1812', 'The Mexican-American War'], explanation: 'The American Civil War was fought primarily over the issue of slavery and states\' rights. It remains the deadliest conflict in American history with an estimated 620,000 to 750,000 soldier deaths.' },
  { id: 'hist-31', category: 'history', difficulty: 'easy', question: 'What civilization built the Parthenon?', answer: 'Ancient Greece', options: ['Ancient Rome', 'Ancient Greece', 'Ancient Egypt', 'Ancient Persia'], explanation: 'The Parthenon was built between 447 and 432 BC in Athens as a temple to the goddess Athena. It was designed by architects Ictinus and Callicrates under the supervision of sculptor Phidias.' },
  { id: 'hist-32', category: 'history', difficulty: 'easy', question: 'What explorer is credited with the first circumnavigation of the Earth?', answer: 'Ferdinand Magellan', options: ['Christopher Columbus', 'Ferdinand Magellan', 'Vasco da Gama', 'Francis Drake'], explanation: 'Magellan\'s expedition departed Spain in 1519, though Magellan himself was killed in the Philippines in 1521. Juan Sebastian Elcano completed the voyage with the remaining crew in 1522.' },
  { id: 'hist-33', category: 'history', difficulty: 'easy', question: 'In what city were the first modern Olympic Games held in 1896?', answer: 'Athens', options: ['Paris', 'Athens', 'London', 'Rome'], explanation: 'The 1896 Athens Olympics featured 241 athletes from 14 nations competing in 43 events. The games were revived by Pierre de Coubertin, inspired by the ancient Greek Olympics.' },
  { id: 'hist-34', category: 'history', difficulty: 'easy', question: 'What was the name of the Japanese attack that brought the U.S. into World War II?', answer: 'Pearl Harbor', options: ['Midway', 'Pearl Harbor', 'Iwo Jima', 'Okinawa'], explanation: 'Japan attacked Pearl Harbor in Hawaii on December 7, 1941, destroying much of the U.S. Pacific Fleet. President Roosevelt called it "a date which will live in infamy" and Congress declared war the next day.' },
  { id: 'hist-35', category: 'history', difficulty: 'easy', question: 'What empire was ruled by sultans from Istanbul for over 600 years?', answer: 'The Ottoman Empire', options: ['The Mongol Empire', 'The Ottoman Empire', 'The Mughal Empire', 'The Byzantine Empire'], explanation: 'The Ottoman Empire lasted from about 1299 to 1922, when it was dissolved after World War I. At its height under Suleiman the Magnificent, it controlled much of southeastern Europe, western Asia, and North Africa.' },
  { id: 'hist-36', category: 'history', difficulty: 'medium', question: 'What was the first permanent English settlement in North America?', answer: 'Jamestown', options: ['Plymouth', 'Jamestown', 'Roanoke', 'St. Augustine'], explanation: 'Jamestown was founded in Virginia in 1607, thirteen years before the Pilgrims landed at Plymouth. St. Augustine in Florida (1565) was actually the first permanent European settlement, but it was Spanish.' },
  { id: 'hist-37', category: 'history', difficulty: 'medium', question: 'What battle in 1066 saw William the Conqueror defeat King Harold II?', answer: 'Battle of Hastings', options: ['Battle of Hastings', 'Battle of Agincourt', 'Battle of Crecy', 'Battle of Stamford Bridge'], explanation: 'The Battle of Hastings on October 14, 1066, established Norman rule over England. King Harold reportedly died from an arrow to the eye, though this may be legendary.' },
  { id: 'hist-38', category: 'history', difficulty: 'medium', question: 'What was the code name for the German invasion of the Soviet Union in 1941?', answer: 'Operation Barbarossa', options: ['Operation Overlord', 'Operation Barbarossa', 'Operation Sea Lion', 'Operation Valkyrie'], explanation: 'Operation Barbarossa launched on June 22, 1941, and was the largest military operation in history with over 3 million German troops. The name referred to Frederick Barbarossa, the medieval Holy Roman Emperor.' },
  { id: 'hist-39', category: 'history', difficulty: 'medium', question: 'What treaty ended World War I?', answer: 'Treaty of Versailles', options: ['Treaty of Paris', 'Treaty of Versailles', 'Treaty of Ghent', 'Treaty of Westphalia'], explanation: 'The Treaty of Versailles was signed on June 28, 1919, exactly five years after the assassination of Archduke Franz Ferdinand. Its harsh terms on Germany, including massive reparations, contributed to conditions that led to World War II.' },
  { id: 'hist-40', category: 'history', difficulty: 'medium', question: 'Who was the first woman to fly solo across the Atlantic Ocean?', answer: 'Amelia Earhart', options: ['Amelia Earhart', 'Bessie Coleman', 'Harriet Quimby', 'Jacqueline Cochran'], explanation: 'Amelia Earhart completed her solo transatlantic flight on May 20-21, 1932, flying from Newfoundland to Northern Ireland. She disappeared in 1937 while attempting to circumnavigate the globe.' },
  { id: 'hist-41', category: 'history', difficulty: 'medium', question: 'What ancient writing system used wedge-shaped marks on clay tablets?', answer: 'Cuneiform', options: ['Hieroglyphics', 'Cuneiform', 'Linear B', 'Sanskrit'], explanation: 'Cuneiform was developed by the Sumerians in Mesopotamia around 3400 BC and is one of the earliest known writing systems. The name comes from the Latin "cuneus" meaning wedge.' },
  { id: 'hist-42', category: 'history', difficulty: 'medium', question: 'What 1773 protest involved colonists dumping tea into Boston Harbor?', answer: 'The Boston Tea Party', options: ['The Boston Massacre', 'The Boston Tea Party', 'The Stamp Act Riots', 'The Intolerable Acts'], explanation: 'On December 16, 1773, colonists disguised as Mohawk Indians dumped 342 chests of British East India Company tea into the harbor. It was a protest against taxation without representation.' },
  { id: 'hist-43', category: 'history', difficulty: 'medium', question: 'What discovery in 1799 helped scholars decode Egyptian hieroglyphics?', answer: 'The Rosetta Stone', options: ['The Dead Sea Scrolls', 'The Rosetta Stone', 'The Book of the Dead', 'The Narmer Palette'], explanation: 'The Rosetta Stone was found by French soldiers in the Egyptian town of Rosetta (Rashid). It contained the same text in hieroglyphics, Demotic script, and Greek, allowing Jean-Francois Champollion to crack the code in 1822.' },
  { id: 'hist-44', category: 'history', difficulty: 'medium', question: 'What Chinese dynasty built the majority of the Great Wall as it exists today?', answer: 'Ming Dynasty', options: ['Qin Dynasty', 'Han Dynasty', 'Ming Dynasty', 'Tang Dynasty'], explanation: 'While the Qin Dynasty started the wall around 221 BC, the Ming Dynasty (1368-1644) rebuilt and extended most of what survives today. The wall stretches over 13,000 miles in total across northern China.' },
  { id: 'hist-45', category: 'history', difficulty: 'medium', question: 'What explorer reached India by sailing around Africa in 1498?', answer: 'Vasco da Gama', options: ['Vasco da Gama', 'Bartolomeu Dias', 'Ferdinand Magellan', 'Henry the Navigator'], explanation: 'Portuguese explorer Vasco da Gama landed in Calicut, India, in May 1498, opening a sea route from Europe to Asia. Bartolomeu Dias had rounded the Cape of Good Hope earlier in 1488 but did not reach India.' },
  { id: 'hist-46', category: 'history', difficulty: 'medium', question: 'Who led the Haitian Revolution, the only successful slave revolt in history?', answer: 'Toussaint Louverture', options: ['Jean-Jacques Dessalines', 'Toussaint Louverture', 'Henri Christophe', 'Simon Bolivar'], explanation: 'Toussaint Louverture led the revolution beginning in 1791, though he was captured and died in a French prison in 1803. Jean-Jacques Dessalines declared Haiti independent in 1804, making it the first free Black republic.' },
  { id: 'hist-47', category: 'history', difficulty: 'medium', question: 'What was the name of the economic crisis that began with the U.S. stock market crash of 1929?', answer: 'The Great Depression', options: ['The Panic of 1929', 'The Great Depression', 'The Great Recession', 'The Long Depression'], explanation: 'The Great Depression lasted roughly from 1929 to 1939, with unemployment reaching 25% in the United States. The stock market crash on "Black Tuesday," October 29, 1929, is considered the triggering event.' },
  { id: 'hist-48', category: 'history', difficulty: 'medium', question: 'What ancient Greek historian is known as the "Father of History"?', answer: 'Herodotus', options: ['Thucydides', 'Herodotus', 'Plutarch', 'Xenophon'], explanation: 'Herodotus (c. 484-425 BC) wrote "The Histories," an account of the Greco-Persian Wars. The Roman orator Cicero gave him the "Father of History" title, though some critics call him the "Father of Lies" for embellishments.' },
  { id: 'hist-49', category: 'history', difficulty: 'medium', question: 'What 1215 document is considered a foundation of English constitutional law?', answer: 'Magna Carta', options: ['Domesday Book', 'Magna Carta', 'English Bill of Rights', 'Petition of Right'], explanation: 'The Magna Carta established that the king was not above the law and guaranteed rights like trial by jury. Only four original copies of the 1215 Magna Carta survive today.' },
  { id: 'hist-50', category: 'history', difficulty: 'medium', question: 'What was the primary cause of the Irish Potato Famine of 1845-1852?', answer: 'A potato blight', options: ['A drought', 'A potato blight', 'A locust plague', 'A flood'], explanation: 'The blight was caused by the water mold Phytophthora infestans, which destroyed potato crops across Ireland. About one million people died and another million emigrated, reducing Ireland\'s population by roughly 25%.' },
  { id: 'hist-51', category: 'history', difficulty: 'medium', question: 'Who was the Carthaginian general who crossed the Alps with elephants to attack Rome?', answer: 'Hannibal', options: ['Hamilcar', 'Hannibal', 'Scipio', 'Hasdrubal'], explanation: 'Hannibal Barca crossed the Alps in 218 BC during the Second Punic War, one of the most daring military feats in history. He won several major battles in Italy but was ultimately defeated by Scipio Africanus at Zama in 202 BC.' },
  { id: 'hist-52', category: 'history', difficulty: 'medium', question: 'What 1947 event divided British India into two independent nations?', answer: 'Partition of India', options: ['Indian Rebellion', 'Partition of India', 'Salt March', 'Quit India Movement'], explanation: 'The Partition created India and Pakistan as separate nations along religious lines, with Pakistan as a Muslim-majority state. The partition triggered massive migration and violence, with estimates of 1-2 million deaths.' },
  { id: 'hist-53', category: 'history', difficulty: 'medium', question: 'What was the Manhattan Project?', answer: 'The U.S. program to develop the atomic bomb', options: ['A plan to rebuild New York City', 'The U.S. program to develop the atomic bomb', 'A Cold War spy network', 'A NASA space mission'], explanation: 'The Manhattan Project ran from 1942 to 1946, led by physicist J. Robert Oppenheimer and General Leslie Groves. The first atomic bomb was tested at Trinity Site in New Mexico on July 16, 1945.' },
  { id: 'hist-54', category: 'history', difficulty: 'medium', question: 'What civilization created the first known system of writing, around 3400 BC?', answer: 'The Sumerians', options: ['The Egyptians', 'The Sumerians', 'The Chinese', 'The Phoenicians'], explanation: 'The Sumerians of Mesopotamia developed cuneiform writing on clay tablets. They also invented the wheel, the plow, and one of the earliest known legal codes.' },
  { id: 'hist-55', category: 'history', difficulty: 'medium', question: 'Who was the Aztec emperor when Hernan Cortes arrived in Mexico?', answer: 'Montezuma II', options: ['Cuauhtemoc', 'Montezuma II', 'Atahualpa', 'Nezahualcoyotl'], explanation: 'Montezuma II (also spelled Moctezuma) ruled the Aztec Empire from 1502 until his death in 1520. Cortes conquered the Aztec capital Tenochtitlan in 1521 with a combination of Spanish soldiers, indigenous allies, and smallpox.' },
  { id: 'hist-56', category: 'history', difficulty: 'medium', question: 'What war was fought between England and France from 1337 to 1453?', answer: "The Hundred Years' War", options: ['The Wars of the Roses', "The Hundred Years' War", 'The Thirty Years\' War', 'The Seven Years\' War'], explanation: "The Hundred Years' War actually lasted 116 years and was fought over claims to the French throne. Joan of Arc played a pivotal role in turning the tide for France before being burned at the stake in 1431." },
  { id: 'hist-57', category: 'history', difficulty: 'medium', question: 'What revolution began in 1917 and led to the creation of the Soviet Union?', answer: 'The Russian Revolution', options: ['The French Revolution', 'The Russian Revolution', 'The Chinese Revolution', 'The Cuban Revolution'], explanation: 'The Russian Revolution actually consisted of two revolutions in 1917: the February Revolution that toppled the Tsar, and the October Revolution led by the Bolsheviks under Lenin. The Soviet Union was formally established in 1922.' },
  { id: 'hist-58', category: 'history', difficulty: 'medium', question: 'What canal, completed in 1914, connects the Atlantic and Pacific Oceans?', answer: 'The Panama Canal', options: ['The Suez Canal', 'The Panama Canal', 'The Erie Canal', 'The Corinth Canal'], explanation: 'The Panama Canal was a massive engineering feat that took 10 years to build and cost over 25,000 worker lives, mostly from disease. France attempted it first in 1881 but abandoned the project; the United States took over in 1904.' },
  { id: 'hist-59', category: 'history', difficulty: 'medium', question: 'Who delivered the "I Have a Dream" speech in 1963?', answer: 'Martin Luther King Jr.', options: ['Malcolm X', 'Martin Luther King Jr.', 'John F. Kennedy', 'Frederick Douglass'], explanation: 'Dr. King delivered the speech on August 28, 1963, during the March on Washington to an audience of about 250,000 people. He was assassinated in Memphis, Tennessee, on April 4, 1968.' },
  { id: 'hist-60', category: 'history', difficulty: 'medium', question: 'What ancient Roman city was buried by the eruption of Mount Vesuvius in 79 AD?', answer: 'Pompeii', options: ['Pompeii', 'Carthage', 'Troy', 'Babylon'], explanation: 'Pompeii and neighboring Herculaneum were buried under volcanic ash and pumice. The preserved ruins were rediscovered in 1748 and provide an extraordinary snapshot of Roman daily life.' },
  { id: 'hist-61', category: 'history', difficulty: 'medium', question: 'What was the Domesday Book?', answer: 'A survey of England ordered by William the Conqueror', options: ['A medieval prophecy text', 'A survey of England ordered by William the Conqueror', 'A record of Black Death victims', 'A collection of Anglo-Saxon laws'], explanation: 'Completed in 1086, the Domesday Book was a comprehensive survey of landholding and resources in England. It was used to determine taxes and is considered one of the most remarkable administrative documents in history.' },
  { id: 'hist-62', category: 'history', difficulty: 'medium', question: 'What Greek city-state was known for its military discipline and warrior culture?', answer: 'Sparta', options: ['Athens', 'Sparta', 'Corinth', 'Thebes'], explanation: 'Spartan boys began military training at age 7 in a system called the agoge. The famous last stand of 300 Spartans under King Leonidas at Thermopylae in 480 BC became legendary.' },
  { id: 'hist-63', category: 'history', difficulty: 'medium', question: 'What 1955 event in Montgomery, Alabama, sparked the civil rights bus boycott?', answer: 'Rosa Parks refused to give up her bus seat', options: ['A church bombing', 'Rosa Parks refused to give up her bus seat', 'A lunch counter sit-in', 'A Freedom Ride'], explanation: 'Rosa Parks was arrested on December 1, 1955, for refusing to give her seat to a white passenger. The subsequent Montgomery Bus Boycott lasted 381 days and was one of the first major victories of the civil rights movement.' },
  { id: 'hist-64', category: 'history', difficulty: 'medium', question: 'What Chinese philosopher founded a philosophy based on ethics, family loyalty, and social harmony?', answer: 'Confucius', options: ['Lao Tzu', 'Confucius', 'Sun Tzu', 'Mencius'], explanation: 'Confucius (551-479 BC) emphasized moral integrity, respect for elders, and proper social relationships. His teachings, collected in the Analects, influenced Chinese culture and government for over 2,000 years.' },
  { id: 'hist-65', category: 'history', difficulty: 'medium', question: 'What medieval event killed an estimated one-third of Europe\'s population?', answer: 'The Black Death', options: ['The Crusades', 'The Black Death', 'The Great Famine', 'The Hundred Years\' War'], explanation: 'The Black Death (bubonic plague) swept through Europe from 1347 to 1351, killing an estimated 25-50 million people. It was spread by fleas on rats and had profound effects on European society, economy, and religion.' },
  { id: 'hist-66', category: 'history', difficulty: 'medium', question: 'Who was the first European to reach the southern tip of Africa?', answer: 'Bartolomeu Dias', options: ['Vasco da Gama', 'Bartolomeu Dias', 'Prince Henry', 'Ferdinand Magellan'], explanation: 'Portuguese explorer Bartolomeu Dias rounded the Cape of Good Hope in 1488. He named it the "Cape of Storms," but King John II of Portugal renamed it the "Cape of Good Hope" for the promising trade route it opened.' },
  { id: 'hist-67', category: 'history', difficulty: 'medium', question: 'What 1848 event in California triggered a massive westward migration?', answer: 'The Gold Rush', options: ['The Gold Rush', 'The Oregon Trail opening', 'The Transcontinental Railroad', 'The Homestead Act'], explanation: 'Gold was discovered at Sutter\'s Mill on January 24, 1848, by James W. Marshall. About 300,000 people came to California during the Gold Rush, and San Francisco grew from a small settlement to a boomtown.' },
  { id: 'hist-68', category: 'history', difficulty: 'medium', question: 'What system of forced labor existed in medieval Europe where peasants were tied to land?', answer: 'Feudalism', options: ['Mercantilism', 'Feudalism', 'Communism', 'Imperialism'], explanation: 'Under feudalism, lords granted land (fiefs) to vassals in exchange for military service, while serfs worked the land. The system dominated European society from roughly the 9th to 15th centuries.' },
  { id: 'hist-69', category: 'history', difficulty: 'medium', question: 'What island did Napoleon Bonaparte get exiled to after his final defeat?', answer: 'Saint Helena', options: ['Elba', 'Saint Helena', 'Corsica', 'Sicily'], explanation: 'Napoleon was exiled to Saint Helena in the South Atlantic after his defeat at Waterloo in 1815, where he died in 1821. He had previously been exiled to Elba in 1814 but famously escaped and returned to power for the Hundred Days.' },
  { id: 'hist-70', category: 'history', difficulty: 'medium', question: 'What ancient city\'s walls supposedly fell when Joshua\'s army blew trumpets?', answer: 'Jericho', options: ['Jericho', 'Babylon', 'Jerusalem', 'Nineveh'], explanation: 'According to the Book of Joshua, the walls of Jericho fell after the Israelites marched around them for seven days. Archaeological evidence shows Jericho is one of the oldest continuously inhabited cities in the world, dating back over 10,000 years.' },
  { id: 'hist-71', category: 'history', difficulty: 'medium', question: 'Who was the first man to walk on the Moon?', answer: 'Neil Armstrong', options: ['Buzz Aldrin', 'Neil Armstrong', 'John Glenn', 'Alan Shepard'], explanation: 'Neil Armstrong stepped onto the lunar surface on July 20, 1969, during the Apollo 11 mission. His famous words were "That\'s one small step for man, one giant leap for mankind."' },
  { id: 'hist-72', category: 'history', difficulty: 'medium', question: 'What was the name of the policy of racial segregation in South Africa?', answer: 'Apartheid', options: ['Jim Crow', 'Apartheid', 'Segregation', 'Colonialism'], explanation: 'Apartheid was enforced from 1948 to 1991 by the National Party government of South Africa. Nelson Mandela spent 27 years in prison fighting against it and became the country\'s first Black president in 1994.' },
  { id: 'hist-73', category: 'history', difficulty: 'medium', question: 'What year did the Titanic sink?', answer: '1912', options: ['1905', '1910', '1912', '1915'], explanation: 'The RMS Titanic struck an iceberg on April 14, 1912, and sank in the early morning hours of April 15 on her maiden voyage. Over 1,500 of the estimated 2,224 passengers and crew died, making it one of the deadliest peacetime maritime disasters.' },
  { id: 'hist-74', category: 'history', difficulty: 'medium', question: 'What Southeast Asian country was formerly known as Siam?', answer: 'Thailand', options: ['Vietnam', 'Thailand', 'Cambodia', 'Myanmar'], explanation: 'Siam officially changed its name to Thailand in 1939, meaning "Land of the Free." It is the only Southeast Asian country that was never colonized by a European power.' },
  { id: 'hist-75', category: 'history', difficulty: 'medium', question: 'What were the military expeditions by European Christians to reclaim the Holy Land called?', answer: 'The Crusades', options: ['The Reconquista', 'The Crusades', 'The Inquisition', 'The Reformation'], explanation: 'The Crusades were a series of religious wars between 1096 and 1291, primarily aimed at recapturing Jerusalem from Muslim control. The First Crusade was the most successful, capturing Jerusalem in 1099.' },
  { id: 'hist-76', category: 'history', difficulty: 'medium', question: 'What was the first battle of the American Revolution?', answer: 'Battles of Lexington and Concord', options: ['Battle of Bunker Hill', 'Battles of Lexington and Concord', 'Battle of Saratoga', 'Battle of Long Island'], explanation: 'The Battles of Lexington and Concord were fought on April 19, 1775, often called "the shot heard round the world." British troops were attempting to seize colonial weapons stores in Concord, Massachusetts.' },
  { id: 'hist-77', category: 'history', difficulty: 'medium', question: 'What empire did Suleiman the Magnificent rule?', answer: 'The Ottoman Empire', options: ['The Persian Empire', 'The Ottoman Empire', 'The Mughal Empire', 'The Byzantine Empire'], explanation: 'Suleiman ruled the Ottoman Empire from 1520 to 1566, its longest reign and golden age. Under his rule, the empire stretched from Hungary to the Persian Gulf and across North Africa.' },
  { id: 'hist-78', category: 'history', difficulty: 'medium', question: 'What was the Iron Curtain?', answer: 'The political boundary dividing Europe during the Cold War', options: ['A medieval fortification', 'The political boundary dividing Europe during the Cold War', 'A British naval blockade', 'A Chinese defensive wall'], explanation: 'Winston Churchill popularized the term in a 1946 speech, describing the divide between Western democracies and Soviet-controlled Eastern Europe. The Iron Curtain lasted from roughly 1945 to 1991.' },
  { id: 'hist-79', category: 'history', difficulty: 'medium', question: 'What was the largest empire in world history by land area?', answer: 'The British Empire', options: ['The Mongol Empire', 'The British Empire', 'The Roman Empire', 'The Russian Empire'], explanation: 'The British Empire at its peak in 1920 covered about 13.7 million square miles, roughly a quarter of the Earth\'s land area. The Mongol Empire was the largest contiguous (connected) land empire, but the British Empire was larger in total area.' },
  { id: 'hist-80', category: 'history', difficulty: 'medium', question: 'What country was the first to give women the right to vote in national elections?', answer: 'New Zealand', options: ['United States', 'United Kingdom', 'New Zealand', 'Australia'], explanation: 'New Zealand granted women the right to vote in 1893, thanks largely to the efforts of suffragist Kate Sheppard. The United States did not grant women\'s suffrage nationally until the 19th Amendment in 1920.' },
  { id: 'hist-81', category: 'history', difficulty: 'medium', question: 'What Roman emperor made Christianity the official religion of the empire?', answer: 'Theodosius I', options: ['Constantine', 'Theodosius I', 'Nero', 'Justinian'], explanation: 'Theodosius I made Christianity the state religion in 380 AD with the Edict of Thessalonica. Constantine had legalized Christianity earlier with the Edict of Milan in 313 AD, but did not make it the official religion.' },
  { id: 'hist-82', category: 'history', difficulty: 'medium', question: 'The Industrial Revolution began in which country?', answer: 'England', options: ['France', 'Germany', 'England', 'United States'], explanation: 'The Industrial Revolution began in England in the mid-18th century, driven by innovations in textile manufacturing, steam power, and iron production. James Watt\'s improvements to the steam engine in the 1760s were a key catalyst.' },
  { id: 'hist-83', category: 'history', difficulty: 'medium', question: 'What was the name of the program to rebuild Europe after World War II?', answer: 'The Marshall Plan', options: ['The New Deal', 'The Marshall Plan', 'The Truman Doctrine', 'The Lend-Lease Act'], explanation: 'The Marshall Plan (officially the European Recovery Program) was proposed by Secretary of State George C. Marshall in 1947. The U.S. provided over $13 billion (about $150 billion today) to help rebuild Western European economies.' },
  { id: 'hist-84', category: 'history', difficulty: 'medium', question: 'What famous library of the ancient world was located in Egypt?', answer: 'The Library of Alexandria', options: ['The Library of Alexandria', 'The Library of Pergamum', 'The Library of Ashurbanipal', 'The Library of Celsus'], explanation: 'The Library of Alexandria was one of the largest and most significant libraries of the ancient world, founded in the 3rd century BC. Its destruction, which happened gradually over centuries, is often cited as a great loss of ancient knowledge.' },
  { id: 'hist-85', category: 'history', difficulty: 'medium', question: 'What 1962 event brought the U.S. and Soviet Union closest to nuclear war?', answer: 'The Cuban Missile Crisis', options: ['The Berlin Blockade', 'The Cuban Missile Crisis', 'The Bay of Pigs', 'The U-2 Incident'], explanation: 'The Cuban Missile Crisis lasted 13 days in October 1962 after U.S. spy planes discovered Soviet nuclear missiles being installed in Cuba. President Kennedy imposed a naval blockade, and the crisis was resolved through secret negotiations.' },
  { id: 'hist-86', category: 'history', difficulty: 'medium', question: 'What ancient Greek philosopher was the teacher of Alexander the Great?', answer: 'Aristotle', options: ['Socrates', 'Plato', 'Aristotle', 'Pythagoras'], explanation: 'Aristotle tutored the young Alexander from age 13 to 16 in Macedonia. Aristotle himself was a student of Plato, who was a student of Socrates, forming a famous chain of philosophical mentorship.' },
  { id: 'hist-87', category: 'history', difficulty: 'medium', question: 'What device did Eli Whitney invent in 1793 that transformed cotton production?', answer: 'The cotton gin', options: ['The spinning jenny', 'The cotton gin', 'The power loom', 'The sewing machine'], explanation: 'The cotton gin could separate cotton fibers from seeds 50 times faster than manual labor. Ironically, rather than reducing slavery, it massively increased demand for slave labor to grow more cotton.' },
  { id: 'hist-88', category: 'history', difficulty: 'medium', question: 'What African kingdom was known for its wealth and the famous pilgrimage of Mansa Musa?', answer: 'Mali Empire', options: ['Ghana Empire', 'Mali Empire', 'Songhai Empire', 'Kingdom of Kush'], explanation: 'Mansa Musa\'s 1324 pilgrimage to Mecca was so lavish that he crashed the gold market in Cairo by distributing gold freely. The Mali Empire was one of the wealthiest empires in world history at the time.' },
  { id: 'hist-89', category: 'history', difficulty: 'medium', question: 'What was the significance of the Battle of Saratoga in 1777?', answer: 'It convinced France to ally with the Americans', options: ['It was the first battle of the war', 'It convinced France to ally with the Americans', 'It ended the Revolutionary War', 'It was the bloodiest battle'], explanation: 'The American victory at Saratoga is considered the turning point of the Revolutionary War. The French alliance brought money, supplies, troops, and crucially, naval power to the American cause.' },
  { id: 'hist-90', category: 'history', difficulty: 'medium', question: 'Who was the first Tsar of Russia?', answer: 'Ivan the Terrible', options: ['Peter the Great', 'Ivan the Terrible', 'Nicholas I', 'Alexander I'], explanation: 'Ivan IV (Ivan the Terrible) was crowned the first Tsar of Russia in 1547 at age 16. His nickname "Grozny" is better translated as "formidable" or "awe-inspiring" rather than "terrible."' },
  { id: 'hist-91', category: 'history', difficulty: 'hard', question: 'What ancient Mesopotamian king created one of the first written law codes around 1754 BC?', answer: 'Hammurabi', options: ['Sargon', 'Hammurabi', 'Nebuchadnezzar', 'Gilgamesh'], explanation: 'Hammurabi\'s Code contained 282 laws covering everything from trade to family relations. The famous "eye for an eye" principle originated in this code, inscribed on a seven-foot black stone stele.' },
  { id: 'hist-92', category: 'history', difficulty: 'hard', question: 'What was the Treaty of Tordesillas (1494)?', answer: 'An agreement dividing newly discovered lands between Spain and Portugal', options: ['A peace treaty ending a European war', 'An agreement dividing newly discovered lands between Spain and Portugal', 'A trade agreement between England and France', 'A religious concordat with the Pope'], explanation: 'The Treaty of Tordesillas drew a line through the Atlantic, giving Spain lands to the west and Portugal lands to the east. This is why Brazil speaks Portuguese while most of the rest of Latin America speaks Spanish.' },
  { id: 'hist-93', category: 'history', difficulty: 'hard', question: 'What battle in 331 BC saw Alexander the Great defeat the Persian Empire?', answer: 'Battle of Gaugamela', options: ['Battle of Issus', 'Battle of Marathon', 'Battle of Gaugamela', 'Battle of Thermopylae'], explanation: 'At Gaugamela (in modern Iraq), Alexander defeated Persian King Darius III despite being heavily outnumbered. This decisive victory effectively ended the Achaemenid Persian Empire and made Alexander ruler of the known world.' },
  { id: 'hist-94', category: 'history', difficulty: 'hard', question: 'What 1648 treaty ended the Thirty Years\' War?', answer: 'Peace of Westphalia', options: ['Treaty of Utrecht', 'Peace of Westphalia', 'Treaty of Augsburg', 'Congress of Vienna'], explanation: 'The Peace of Westphalia established the concept of state sovereignty that forms the basis of modern international relations. It ended one of the most destructive wars in European history, which killed roughly 8 million people.' },
  { id: 'hist-95', category: 'history', difficulty: 'hard', question: 'What pharaoh\'s tomb was discovered virtually intact by Howard Carter in 1922?', answer: 'Tutankhamun', options: ['Ramesses II', 'Tutankhamun', 'Akhenaten', 'Khufu'], explanation: 'Tutankhamun\'s tomb in the Valley of the Kings contained over 5,000 artifacts including the iconic gold death mask. The young pharaoh died around age 19 and would have been relatively obscure if not for the tomb\'s discovery.' },
  { id: 'hist-96', category: 'history', difficulty: 'hard', question: 'What ancient Greek battle in 490 BC inspired the modern marathon race?', answer: 'Battle of Marathon', options: ['Battle of Thermopylae', 'Battle of Salamis', 'Battle of Marathon', 'Battle of Plataea'], explanation: 'Legend says the messenger Pheidippides ran approximately 25 miles from Marathon to Athens to announce the Greek victory over Persia. The modern marathon distance of 26.2 miles was standardized at the 1908 London Olympics.' },
  { id: 'hist-97', category: 'history', difficulty: 'hard', question: 'What rebellion in China from 1850 to 1864 was one of the deadliest conflicts in history?', answer: 'Taiping Rebellion', options: ['Boxer Rebellion', 'Taiping Rebellion', 'An Lushan Rebellion', 'White Lotus Rebellion'], explanation: 'The Taiping Rebellion killed an estimated 20-30 million people, making it one of the deadliest wars in human history. It was led by Hong Xiuquan, who claimed to be the brother of Jesus Christ.' },
  { id: 'hist-98', category: 'history', difficulty: 'hard', question: 'Who was the Viking explorer believed to have reached North America around 1000 AD?', answer: 'Leif Erikson', options: ['Erik the Red', 'Leif Erikson', 'Ragnar Lothbrok', 'Harald Hardrada'], explanation: 'Leif Erikson established a settlement at Vinland, believed to be modern-day Newfoundland, Canada. The archaeological site at L\'Anse aux Meadows confirms Norse presence in North America about 500 years before Columbus.' },
  { id: 'hist-99', category: 'history', difficulty: 'hard', question: 'What 1884-1885 conference divided Africa among European colonial powers?', answer: 'The Berlin Conference', options: ['The Congress of Vienna', 'The Berlin Conference', 'The Treaty of Paris', 'The Hague Convention'], explanation: 'The Berlin Conference, organized by Otto von Bismarck, established rules for the European colonization of Africa. No African representatives were invited, and by 1914, European nations controlled about 90% of the continent.' },
  { id: 'hist-100', category: 'history', difficulty: 'hard', question: 'What was the Defenestration of Prague?', answer: 'Throwing Catholic officials out of a window, sparking the Thirty Years\' War', options: ['A plague outbreak in Prague', 'Throwing Catholic officials out of a window, sparking the Thirty Years\' War', 'The siege and destruction of Prague Castle', 'A Protestant massacre in Bohemia'], explanation: 'On May 23, 1618, angry Protestant nobles threw two Catholic imperial governors and their secretary out of a third-story window of Prague Castle. Remarkably, all three survived the 70-foot fall, which Catholics attributed to angels and Protestants attributed to a dung heap.' },
  { id: 'hist-101', category: 'history', difficulty: 'hard', question: 'What Roman general crossed the Rubicon River in 49 BC, triggering a civil war?', answer: 'Julius Caesar', options: ['Pompey', 'Julius Caesar', 'Marcus Crassus', 'Mark Antony'], explanation: 'By crossing the Rubicon with his army, Caesar violated Roman law and effectively declared war on the Senate. The phrase "crossing the Rubicon" now means passing a point of no return.' },
  { id: 'hist-102', category: 'history', difficulty: 'hard', question: 'What 18th-century conflict is often called the first true "world war"?', answer: "The Seven Years' War", options: ['The War of Spanish Succession', "The Seven Years' War", 'The Napoleonic Wars', 'The War of Austrian Succession'], explanation: "The Seven Years' War (1756-1763) was fought across five continents between major European powers and their colonies. In North America, it is known as the French and Indian War." },
  { id: 'hist-103', category: 'history', difficulty: 'hard', question: 'What Persian king invaded Greece in 480 BC with a massive army?', answer: 'Xerxes I', options: ['Cyrus the Great', 'Darius I', 'Xerxes I', 'Artaxerxes'], explanation: 'Xerxes I assembled one of the largest armies of the ancient world for his invasion of Greece. He was famously delayed by the 300 Spartans at Thermopylae before his navy was defeated at the Battle of Salamis.' },
  { id: 'hist-104', category: 'history', difficulty: 'hard', question: 'What 1854-1856 war saw Britain and France fight against Russia in the Black Sea region?', answer: 'The Crimean War', options: ['The Russo-Turkish War', 'The Crimean War', 'The Boer War', 'The Franco-Prussian War'], explanation: 'The Crimean War is notable for Florence Nightingale\'s pioneering nursing work and as one of the first wars with extensive press coverage. The disastrous Charge of the Light Brigade at Balaclava became one of the war\'s most famous events.' },
  { id: 'hist-105', category: 'history', difficulty: 'hard', question: 'What ancient trade city, carved into rock cliffs, was the capital of the Nabataean Kingdom?', answer: 'Petra', options: ['Palmyra', 'Petra', 'Persepolis', 'Pergamon'], explanation: 'Petra, in modern-day Jordan, was a thriving trade hub from the 4th century BC. The city\'s most famous structure, Al-Khazneh (The Treasury), was carved directly into a sandstone cliff face.' },
  { id: 'hist-106', category: 'history', difficulty: 'hard', question: 'What was the Reconquista?', answer: 'The centuries-long Christian reconquest of the Iberian Peninsula from the Moors', options: ['The Spanish colonization of the Americas', 'The centuries-long Christian reconquest of the Iberian Peninsula from the Moors', 'The Portuguese exploration of Africa', 'The Italian unification movement'], explanation: 'The Reconquista lasted from 718 to 1492, ending when Ferdinand and Isabella conquered Granada, the last Muslim stronghold. That same year, they also sponsored Columbus\'s voyage and expelled Jews from Spain.' },
  { id: 'hist-107', category: 'history', difficulty: 'hard', question: 'Who was the Zulu king who created a formidable military force in southern Africa?', answer: 'Shaka Zulu', options: ['Cetshwayo', 'Shaka Zulu', 'Dingane', 'Mzilikazi'], explanation: 'Shaka Zulu (c. 1787-1828) transformed the Zulu from a small clan into a powerful nation through military innovations. He introduced the short stabbing spear (iklwa) and the "buffalo horns" formation that revolutionized warfare in southern Africa.' },
  { id: 'hist-108', category: 'history', difficulty: 'hard', question: 'What ancient civilization, centered in modern-day Pakistan, had advanced urban planning around 2500 BC?', answer: 'The Indus Valley Civilization', options: ['The Maurya Empire', 'The Indus Valley Civilization', 'The Gupta Empire', 'The Vedic Civilization'], explanation: 'The Indus Valley Civilization (also called Harappan) had cities like Mohenjo-daro with grid-pattern streets, indoor plumbing, and public baths. It was one of the three earliest urban civilizations, alongside Mesopotamia and Egypt.' },
  { id: 'hist-109', category: 'history', difficulty: 'hard', question: 'What 1839-1842 conflict was fought over British opium trade in China?', answer: 'The First Opium War', options: ['The Boxer Rebellion', 'The First Opium War', 'The Taiping Rebellion', 'The Sino-Japanese War'], explanation: 'Britain went to war with Qing Dynasty China after China tried to ban the opium trade that was causing widespread addiction. China\'s defeat led to the Treaty of Nanking, which ceded Hong Kong to Britain and opened five treaty ports.' },
  { id: 'hist-110', category: 'history', difficulty: 'hard', question: 'What document, issued by Napoleon in 1804, formed the basis of civil law in many countries?', answer: 'The Napoleonic Code', options: ['The Declaration of the Rights of Man', 'The Napoleonic Code', 'The Code of Justinian', 'The French Constitution'], explanation: 'The Napoleonic Code (Code Civil) established clear, accessible laws covering property, family, and individual rights. It influenced the legal systems of over 40 countries and remains the basis of French civil law today.' },
  { id: 'hist-111', category: 'history', difficulty: 'hard', question: 'What 1905 event, known as "Bloody Sunday," helped spark the Russian Revolution?', answer: 'Tsarist troops fired on peaceful protesters in St. Petersburg', options: ['The assassination of Tsar Alexander II', 'Tsarist troops fired on peaceful protesters in St. Petersburg', 'A workers\' strike in Moscow', 'The mutiny on the Battleship Potemkin'], explanation: 'On January 22, 1905, Imperial guards fired on workers peacefully marching to petition Tsar Nicholas II, killing hundreds. This massacre destroyed the people\'s faith in the Tsar and led to the Revolution of 1905.' },
  { id: 'hist-112', category: 'history', difficulty: 'hard', question: 'What was the Congress of Vienna (1814-1815)?', answer: 'A diplomatic meeting to reorganize Europe after Napoleon\'s defeat', options: ['A meeting to plan the Crusades', 'A diplomatic meeting to reorganize Europe after Napoleon\'s defeat', 'The founding of the United Nations', 'A trade agreement between European powers'], explanation: 'The Congress of Vienna, led by Austrian diplomat Klemens von Metternich, redrew the map of Europe after the Napoleonic Wars. It established a balance of power that largely maintained peace in Europe for nearly a century until World War I.' },
  { id: 'hist-113', category: 'history', difficulty: 'hard', question: 'What ancient people developed an alphabet that became the basis for Greek and Latin writing?', answer: 'The Phoenicians', options: ['The Sumerians', 'The Egyptians', 'The Phoenicians', 'The Hittites'], explanation: 'The Phoenician alphabet, developed around 1050 BC in modern-day Lebanon, was the first widely used phonetic alphabet. The Phoenicians were also master sailors and traders who founded Carthage and traded across the Mediterranean.' },
  { id: 'hist-114', category: 'history', difficulty: 'hard', question: 'What battle in 1805 established British naval supremacy for a century?', answer: 'Battle of Trafalgar', options: ['Battle of the Nile', 'Battle of Trafalgar', 'Battle of Jutland', 'Battle of Lepanto'], explanation: 'Admiral Horatio Nelson defeated the combined French and Spanish fleets off the coast of Spain on October 21, 1805. Nelson was killed during the battle but became Britain\'s greatest naval hero. Trafalgar Square in London is named for the victory.' },
  { id: 'hist-115', category: 'history', difficulty: 'hard', question: 'What ancient Greek device, found in a shipwreck, is considered the first analog computer?', answer: 'The Antikythera mechanism', options: ['The Archimedes screw', 'The Antikythera mechanism', 'The Aeolipile', 'The Astrolabe'], explanation: 'The Antikythera mechanism dates to about 100 BC and was used to predict astronomical positions and eclipses. Discovered in 1901, it contained over 30 bronze gears and was far more complex than anything else built for the next 1,000 years.' },
  { id: 'hist-116', category: 'history', difficulty: 'hard', question: 'What dynasty unified China for the first time in 221 BC?', answer: 'Qin Dynasty', options: ['Han Dynasty', 'Qin Dynasty', 'Zhou Dynasty', 'Shang Dynasty'], explanation: 'Qin Shi Huang became the first Emperor of a unified China and standardized weights, measures, currency, and writing. The Qin Dynasty lasted only 15 years but left a lasting legacy, including the beginning of the Great Wall and the Terracotta Army.' },
  { id: 'hist-117', category: 'history', difficulty: 'hard', question: 'What medieval Italian traveler spent 24 years in Asia and wrote about his experiences at the court of Kublai Khan?', answer: 'Marco Polo', options: ['Marco Polo', 'Ibn Battuta', 'Amerigo Vespucci', 'Giovanni da Verrazzano'], explanation: 'Marco Polo traveled to China in 1271 and served in the court of Kublai Khan for 17 years. His book "The Travels of Marco Polo" introduced Europeans to Central Asia and China and inspired future explorers, including Columbus.' },
  { id: 'hist-118', category: 'history', difficulty: 'hard', question: 'What 1857 uprising against British rule in India was initially sparked by Indian soldiers (sepoys)?', answer: 'The Indian Rebellion of 1857', options: ['The Salt March', 'The Indian Rebellion of 1857', 'The Quit India Movement', 'The Amritsar Massacre'], explanation: 'Also called the Sepoy Mutiny, it was triggered partly by the rumor that rifle cartridges were greased with cow and pig fat, offensive to Hindu and Muslim soldiers. The rebellion led to the dissolution of the East India Company and direct British Crown rule over India.' },
  { id: 'hist-119', category: 'history', difficulty: 'hard', question: 'What was the last dynasty to rule China before the Republic was established in 1912?', answer: 'Qing Dynasty', options: ['Ming Dynasty', 'Qing Dynasty', 'Yuan Dynasty', 'Tang Dynasty'], explanation: 'The Qing Dynasty (1644-1912) was established by the Manchu people from northeastern China. Its collapse ended over 2,000 years of imperial rule in China.' },
  { id: 'hist-120', category: 'history', difficulty: 'hard', question: 'What decisive 1571 naval battle halted Ottoman expansion in the Mediterranean?', answer: 'Battle of Lepanto', options: ['Battle of Trafalgar', 'Battle of Actium', 'Battle of Lepanto', 'Battle of Salamis'], explanation: 'The Battle of Lepanto saw a coalition of Catholic states, the Holy League, defeat the Ottoman fleet off the coast of Greece. It was the last major naval battle fought primarily between rowing vessels (galleys).' },
  { id: 'hist-121', category: 'history', difficulty: 'hard', question: 'What Roman emperor divided the empire into eastern and western halves for administrative purposes?', answer: 'Diocletian', options: ['Constantine', 'Diocletian', 'Theodosius', 'Augustus'], explanation: 'Diocletian established the Tetrarchy in 293 AD, dividing the empire into four administrative units under two senior and two junior emperors. This division eventually became permanent, with the Western Roman Empire falling in 476 AD while the Eastern (Byzantine) Empire survived until 1453.' },
  { id: 'hist-122', category: 'history', difficulty: 'hard', question: 'What Mesoamerican civilization is known for developing a precise calendar and the concept of zero?', answer: 'The Maya', options: ['The Aztec', 'The Maya', 'The Olmec', 'The Inca'], explanation: 'The Maya developed a sophisticated mathematical system using base 20 and independently invented the concept of zero around 350 AD. Their Long Count calendar, which some misinterpreted as predicting the end of the world in 2012, was actually marking the end of a calendrical cycle.' },
  { id: 'hist-123', category: 'history', difficulty: 'hard', question: 'What 1453 event marked the end of the Byzantine Empire?', answer: 'The Fall of Constantinople to the Ottoman Turks', options: ['The Fourth Crusade', 'The Fall of Constantinople to the Ottoman Turks', 'The Battle of Manzikert', 'The Sack of Rome'], explanation: 'Ottoman Sultan Mehmed II captured Constantinople on May 29, 1453, using massive cannons to breach the ancient walls. This ended over 1,000 years of the Byzantine Empire and many historians consider it the end of the Middle Ages.' },
  { id: 'hist-124', category: 'history', difficulty: 'hard', question: 'What governing body oversaw the French Revolution\'s Reign of Terror?', answer: 'Committee of Public Safety', options: ['The Gendarmerie', 'Committee of Public Safety', 'The National Guard', 'The Jacobin Guard'], explanation: 'The Committee of Public Safety, led by Maximilien Robespierre, oversaw the Reign of Terror (1793-94) in which an estimated 16,000-40,000 people were executed. Robespierre himself was eventually arrested and guillotined in July 1794.' },
  { id: 'hist-125', category: 'history', difficulty: 'hard', question: 'What was the significance of the Battle of Tours (732 AD)?', answer: 'It halted the Muslim advance into Western Europe', options: ['It began the First Crusade', 'It halted the Muslim advance into Western Europe', 'It unified the Frankish kingdom', 'It ended Viking raids in France'], explanation: 'Charles Martel led the Frankish army to defeat the Umayyad Caliphate forces near Tours, France. Many historians consider it one of the most decisive battles in world history, preserving Christianity in Western Europe.' },
]
